import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Reconciliation","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/reconciliation.md","filePath":"concepts/reconciliation.md"}'),i={name:"concepts/reconciliation.md"};function r(o,e,l,c,p,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="reconciliation" tabindex="-1">Reconciliation <a class="header-anchor" href="#reconciliation" aria-label="Permalink to &quot;Reconciliation&quot;">​</a></h1><p>The reconciliation loop is the heart of CCattler. Every capability — scheduling, scaling, networking, storage, failure recovery — runs through this single mechanism.</p><h2 id="the-loop" tabindex="-1">The loop <a class="header-anchor" href="#the-loop" aria-label="Permalink to &quot;The loop&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>facts → rules/queries → new facts → actions → real world → observed facts → repeat</span></span></code></pre></div><p>At each tick:</p><ol><li>Controllers read the current state from the fact store</li><li>They compare desired state against observed state</li><li>They propose changes to close the gap</li><li>Changes are committed transactionally</li><li>Node agents actuate the changes in the real world</li><li>Agents report new observed state back to the store</li></ol><p>The loop repeats continuously. A 30-second periodic resync runs as a safety net, ensuring convergence even if watch events are missed.</p><h2 id="five-architectural-rules" tabindex="-1">Five architectural rules <a class="header-anchor" href="#five-architectural-rules" aria-label="Permalink to &quot;Five architectural rules&quot;">​</a></h2><h3 id="_1-no-component-may-assume-another-component-performed-an-action" tabindex="-1">1. No component may assume another component performed an action <a class="header-anchor" href="#_1-no-component-may-assume-another-component-performed-an-action" aria-label="Permalink to &quot;1. No component may assume another component performed an action&quot;">​</a></h3><p>Components only react to state. The scheduler writes a placement fact; the network controller notices it. They never call each other.</p><h3 id="_2-desired-state-and-observed-state-are-always-separate" tabindex="-1">2. Desired state and observed state are always separate <a class="header-anchor" href="#_2-desired-state-and-observed-state-are-always-separate" aria-label="Permalink to &quot;2. Desired state and observed state are always separate&quot;">​</a></h3><p>Never overwrite desired with reality. The difference between them is the work.</p><h3 id="_3-idempotency-is-the-fundamental-primitive" tabindex="-1">3. Idempotency is the fundamental primitive <a class="header-anchor" href="#_3-idempotency-is-the-fundamental-primitive" aria-label="Permalink to &quot;3. Idempotency is the fundamental primitive&quot;">​</a></h3><p>Every operation is <code>ensure_X()</code>, not <code>do_X()</code>. Safe to repeat. <code>ensure_running(container)</code>, not <code>start_container()</code>.</p><h3 id="_4-store-facts-and-desired-results-not-commands" tabindex="-1">4. Store facts and desired results, not commands <a class="header-anchor" href="#_4-store-facts-and-desired-results-not-commands" aria-label="Permalink to &quot;4. Store facts and desired results, not commands&quot;">​</a></h3><p><code>desired(instance, running)</code> not <code>start(instance)</code>. This makes the system naturally retryable — if an action fails, the gap between desired and actual persists and the agent tries again.</p><h3 id="_5-controllers-return-proposed-changes-not-arbitrary-mutations" tabindex="-1">5. Controllers return proposed changes, not arbitrary mutations <a class="header-anchor" href="#_5-controllers-return-proposed-changes-not-arbitrary-mutations" aria-label="Permalink to &quot;5. Controllers return proposed changes, not arbitrary mutations&quot;">​</a></h3><p><code>reconcile(facts) → []change</code>, validated and committed transactionally by the command layer.</p><h2 id="controller-interface" tabindex="-1">Controller interface <a class="header-anchor" href="#controller-interface" aria-label="Permalink to &quot;Controller interface&quot;">​</a></h2><p>Every controller implements:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Controller</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Watch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // fact prefixes to observe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Reconcile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">facts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) []</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Change</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // proposed changes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The runner framework handles the watch → reconcile → commit loop. Controllers are stateless — they can crash and restart without losing information.</p><h2 id="deterministic-testing" tabindex="-1">Deterministic testing <a class="header-anchor" href="#deterministic-testing" aria-label="Permalink to &quot;Deterministic testing&quot;">​</a></h2><p>The entire control plane is deterministic: given state A + observation B + policy C → desired state D. Tests don&#39;t need a cluster:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INPUT:  nodes=[n1:4cpu, n2:4cpu], service=web, desired=5, cpu=1</span></span>
<span class="line"><span>EXPECT: placement=[n1:3, n2:2]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INPUT:  n2=dead</span></span>
<span class="line"><span>EXPECT: placement=[n1:4, unsatisfied=1]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INPUT:  n2=alive</span></span>
<span class="line"><span>EXPECT: placement=[n1:3, n2:2]</span></span></code></pre></div><h2 id="controller-resilience" tabindex="-1">Controller resilience <a class="header-anchor" href="#controller-resilience" aria-label="Permalink to &quot;Controller resilience&quot;">​</a></h2><p>Controllers restart with exponential backoff: 100ms → 500ms → 1s → 2s → 5s → 30s max. The runner manages controller lifecycles and cancels all controllers on failure.</p><p>Multiple controller replicas can run simultaneously — leader election ensures only one is active. If the leader crashes, another takes over.</p><h2 id="chaos-mode" tabindex="-1">Chaos mode <a class="header-anchor" href="#chaos-mode" aria-label="Permalink to &quot;Chaos mode&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cca</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chaos</span></span></code></pre></div><p>Randomly injects: node failures, network delays, process crashes, stale observations, controller restarts, duplicate events, lost messages, slow storage.</p><p>The only assertion: <strong>eventually observed state converges to desired state.</strong></p>`,32)])])}const u=a(i,[["render",r]]);export{m as __pageData,u as default};
